import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene transforms
  group.position.set(...(config.scenePosition || [0, 3, 0]));
  group.rotation.set(...(config.sceneRotation || [0, 0, 0]));
  group.scale.set(...(config.sceneScale || [1, 1, 1]));

  // Create plane geometry (aspect ratio 512:320 ≈ 1.6:1)
  const width = 4;
  const height = width * (320 / 512);
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture
  const textureMap = ctx.textureLoader.load(
    config.imageUrl || '/prism-mock/home/nodes/feature-card.png'
  );

  // Create TSL material with texture
  const materialNode = new MeshBasicNodeMaterial();
  materialNode.colorNode = texture(textureMap, uv());

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, materialNode);
  group.add(mesh);

  // Render text content via fontAtlas
  if (config.textContent && Array.isArray(config.textContent)) {
    for (const textItem of config.textContent) {
      const text = typeof textItem === 'string' ? textItem : (textItem?.text || '');
      const size = textItem?.size || 31;
      const weight = textItem?.weight || 400;

      if (text && ctx.fontAtlas?.renderText) {
        const textMesh = ctx.fontAtlas.renderText(text, {
          size,
          weight,
          family: 'JetBrains Mono',
          color: config.colors?.paper || 0xe8ecf2
        });

        if (textMesh) {
          textMesh.position.z = 0.01;
          group.add(textMesh);
        }
      }
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives?.[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    }
  }

  // Setup resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    materialNode.dispose();
    textureMap.dispose();
    gsap.killTweensOf(group);
  };

  // Setup event handlers
  group.userData.handlers = {};

  return group;
}
